    "verses": [
      {
        "text": "Yahweh himself is who goes before you. He will be with you. He will not fail you nor forsake you. Don’t be afraid. Don’t be discouraged.”",
        "reference": "Deuteronomy 31:8",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "God sets the lonely in families. He brings out the prisoners with singing, but the rebellious dwell in a sun-scorched land.",
        "reference": "Psalm 68:6",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Even though I walk through the valley of the shadow of death, I will fear no evil, for you are with me. Your rod and your staff, they comfort me.",
        "reference": "Psalm 23:4",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Turn to me, and have mercy on me, for I am desolate and afflicted.",
        "reference": "Psalm 25:16",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "teaching them to observe all things that I commanded you. Behold, I am with you always, even to the end of the age.” Amen.",
        "reference": "Matthew 28:20",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "A father of the fatherless, and a defender of the widows, is God in his holy habitation.",
        "reference": "Psalm 68:5",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Be free from the love of money, content with such things as you have, for he has said, “I will in no way leave you, neither will I in any way forsake you.”",
        "reference": "Hebrews 13:5",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Yahweh is near to those who have a broken heart, and saves those who have a crushed spirit.",
        "reference": "Psalm 34:18",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Don’t you be afraid, for I am with you. Don’t be dismayed, for I am your God. I will strengthen you. Yes, I will help you. Yes, I will uphold you with the right hand of my righteousness.",
        "reference": "Isaiah 41:10",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Where could I go from your Spirit? Or where could I flee from your presence?",
        "reference": "Psalm 139:7",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "casting all your worries on him, because he cares for you.",
        "reference": "1 Peter 5:7",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "He heals the broken in heart, and binds up their wounds.",
        "reference": "Psalm 147:3",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "When my father and my mother forsake me, then Yahweh will take me up.",
        "reference": "Psalm 27:10",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Be strong and courageous. Don’t be afraid or scared of them; for Yahweh your God himself is who goes with you. He will not fail you nor forsake you.”",
        "reference": "Deuteronomy 31:6",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Yahweh God said, “It is not good for the man to be alone. I will make him a helper comparable to him.”",
        "reference": "Genesis 2:18",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "I will not leave you orphans. I will come to you.",
        "reference": "John 14:18",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God. And the peace of God, which surpasses all understanding, will guard your hearts and your thoughts in Christ Jesus.",
        "reference": "Philippians 4:6-7",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "No man will be able to stand before you all the days of your life. As I was with Moses, so I will be with you. I will not fail you nor forsake you.",
        "reference": "Joshua 1:5",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "For Yahweh will not forsake his people for his great name’s sake, because it has pleased Yahweh to make you a people for himself.",
        "reference": "1 Samuel 12:22",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Haven’t I commanded you? Be strong and courageous. Don’t be afraid. Don’t be dismayed, for Yahweh your God is with you wherever you go.”",
        "reference": "Joshua 1:9",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Lord, all my desire is before you. My groaning is not hidden from you.",
        "reference": "Psalm 38:9",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "A man of many companions may be ruined, but there is a friend who sticks closer than a brother.",
        "reference": "Proverbs 18:24",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Trust in him at all times, you people. Pour out your heart before him. God is a refuge for us. Selah.",
        "reference": "Psalm 62:8",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "No temptation has taken you except what is common to man. God is faithful, who will not allow you to be tempted above what you are able, but will with the temptation also make the way of escape, that you may be able to endure it.",
        "reference": "1 Corinthians 10:13",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "When you pass through the waters, I will be with you; and through the rivers, they will not overflow you. When you walk through the fire, you will not be burned, and flame will not scorch you.",
        "reference": "Isaiah 43:2",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Who shall separate us from the love of Christ? Could oppression, or anguish, or persecution, or famine, or nakedness, or peril, or sword? Even as it is written, “For your sake we are killed all day long. We were accounted as sheep for the slaughter.” No, in all these things, we are more than conquerors through him who loved us. For I am persuaded that neither death, nor life, nor angels, nor principalities, nor things present, nor things to come, nor powers, nor height, nor depth, nor any other created thing, will be able to separate us from God’s love, which is in Christ Jesus our Lord.",
        "reference": "Romans 8:35-39",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "By this we know that we remain in him and he in us, because he has given us of his Spirit.",
        "reference": "1 John 4:13",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "What then shall we say about these things? If God is for us, who can be against us?",
        "reference": "Romans 8:31",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "Haven’t you known? Haven’t you heard? The everlasting God, Yahweh, The Creator of the ends of the earth, doesn’t faint. He isn’t weary. His understanding is unsearchable. He gives power to the weak. He increases the strength of him who has no might. Even the youths faint and get weary, and the young men utterly fall; But those who wait for Yahweh will renew their strength. They will mount up with wings like eagles. They will run, and not be weary. They will walk, and not faint.",
        "reference": "Isaiah 40:28-31",
        "translation": "WEB",
        "theme": "loneliness"
      },
      {
        "text": "“Come to me, all you who labor and are heavily burdened, and I will give you rest.",
        "reference": "Matthew 11:28",
        "translation": "WEB",
        "theme": "loneliness"
      }
    ],
