    "verses": [
      {
        "text": "In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God.",
        "reference": "Philippians 4:6",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "Anxiety in a man’s heart weighs it down, but a kind word makes it glad.",
        "reference": "Proverbs 12:25",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "Out of my distress, I called on Yah. Yah answered me with freedom. Yahweh is on my side. I will not be afraid. What can man do to me?",
        "reference": "Psalm 118:5-6",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "“Come to me, all you who labor and are heavily burdened, and I will give you rest. Take my yoke upon you, and learn from me, for I am gentle and humble in heart; and you will find rest for your souls. For my yoke is easy, and my burden is light.”",
        "reference": "Matthew 11:28-30",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "What then shall we say about these things? If God is for us, who can be against us?",
        "reference": "Romans 8:31",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "We know that all things work together for good for those who love God, to those who are called according to his purpose.",
        "reference": "Romans 8:28",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "Therefore don’t be anxious for tomorrow, for tomorrow will be anxious for itself. Each day’s own evil is sufficient.",
        "reference": "Matthew 6:34",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "“Which of you, by being anxious, can add one moment to his lifespan?",
        "reference": "Matthew 6:27",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "Blessed is the man who endures temptation, for when he has been approved, he will receive the crown of life, which the Lord promised to those who love him.",
        "reference": "James 1:12",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "But seek first God’s Kingdom, and his righteousness; and all these things will be given to you as well.",
        "reference": "Matthew 6:33",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "Haven’t I commanded you? Be strong and courageous. Don’t be afraid. Don’t be dismayed, for Yahweh your God is with you wherever you go.”",
        "reference": "Joshua 1:9",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "casting all your worries on him, because he cares for you.",
        "reference": "1 Peter 5:7",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "Jesus answered her, “Martha, Martha, you are anxious and troubled about many things, but one thing is needed. Mary has chosen the good part, which will not be taken away from her.”",
        "reference": "Luke 10:41-42",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "Trust in Yahweh with all your heart, and don’t lean on your own understanding. In all your ways acknowledge him, and he will make your paths straight.",
        "reference": "Proverbs 3:5-6",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "Therefore let us also, seeing we are surrounded by so great a cloud of witnesses, lay aside every weight and the sin which so easily entangles us, and let us run with perseverance the race that is set before us,",
        "reference": "Hebrews 12:1",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "He said to his disciples, “Therefore I tell you, don’t be anxious for your life, what you will eat, nor yet for your body, what you will wear.",
        "reference": "Luke 12:22",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "There is no fear in love; but perfect love casts out fear, because fear has punishment. He who fears is not made perfect in love.",
        "reference": "1 John 4:18",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "My heart is troubled, and doesn’t rest. Days of affliction have come on me.",
        "reference": "Job 30:27",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "“Don’t let your heart be troubled. Believe in God. Believe also in me.",
        "reference": "John 14:1",
        "translation": "WEB",
        "theme": "stress"
      },
      {
        "text": "If you falter in the time of trouble, your strength is small.",
        "reference": "Proverbs 24:10",
        "translation": "WEB",
        "theme": "stress"
      }
    ],
